import {LOCATIONS,RELICS} from './expedition.js?v=journey4';
export function drawJourney(c,g,images,clock){
 c.save();
 for(const h of g.hazards){const progress=1-h.life/1.8;c.beginPath();c.arc(h.x,h.y,h.r,0,Math.PI*2);c.fillStyle=h.hit?'#ff713766':'#ff99552a';c.fill();c.lineWidth=3;c.strokeStyle='#ffb28a';c.stroke();c.beginPath();c.arc(h.x,h.y,h.r*Math.min(1,progress/.64),0,Math.PI*2);c.stroke();c.font='bold 16px system-ui';c.textAlign='center';c.fillStyle='#fff0d5';c.fillText('落火',h.x,h.y+5);}
 for(const portal of g.portals){const place=LOCATIONS[portal.destination],pulse=Math.sin(clock*3)*.08+1;c.save();c.translate(portal.x,portal.y);c.shadowColor=place.color;c.shadowBlur=24;c.scale(pulse,pulse);c.beginPath();c.ellipse(0,-18,42,64,0,0,Math.PI*2);c.fillStyle=place.color+'25';c.fill();c.strokeStyle=place.color;c.lineWidth=4;c.stroke();c.shadowBlur=0;c.setLineDash([6,12]);c.lineWidth=1;c.beginPath();c.ellipse(0,-18,33,53,0,clock,clock+Math.PI*2);c.stroke();c.setLineDash([]);c.restore();
  c.save();c.textAlign='center';c.font='bold 18px system-ui';c.lineWidth=4;c.strokeStyle='#061b22';const title=portal.direction+' · '+place.name;c.strokeText(title,portal.x,portal.y-101);c.fillStyle=place.color;c.fillText(title,portal.x,portal.y-101);c.font='14px system-ui';c.strokeText(place.risk,portal.x,portal.y+71);c.fillStyle='#f2f6e9';c.fillText(place.risk,portal.x,portal.y+71);c.restore();
 }
 if(g.chest){const {x,y}=g.chest;const image=images.chest;c.save();c.translate(x,y);c.shadowColor='#ffd77c';c.shadowBlur=20;c.strokeStyle='#e1c18a88';c.lineWidth=2;c.beginPath();c.ellipse(0,16,49,16,0,0,Math.PI*2);c.stroke();c.shadowBlur=0;const frame=g.state==='loot'?1:0;c.drawImage(image,frame*image.width/2,0,image.width/2,image.height,-72,-98,144,144);c.font='bold 16px system-ui';c.textAlign='center';c.strokeStyle='#102d29';c.lineWidth=4;c.strokeText('关卡宝箱',0,-97);c.fillStyle='#ffe2a1';c.fillText('关卡宝箱',0,-97);c.restore();}
 if(g.relics.orb){for(let i=0;i<g.relics.orb;i++){const a=clock*2+i*Math.PI*2/g.relics.orb;c.beginPath();c.arc(g.player.x+Math.cos(a)*85,g.player.y+Math.sin(a)*38,5,0,Math.PI*2);c.fillStyle='#ffe6a2';c.shadowColor='#ffda88';c.shadowBlur=12;c.fill();}}
 c.restore();
}
export function equipmentMarkup(g){const weapon=g.weaponName+' · '+g.weaponLevel+' 级';return `<div class="equipped-main"><small>当前武器 · 改变普攻</small><h3>${weapon}</h3><p>${g.weapon==='native'?'守护者本命攻击，保留原有战斗风格。':({spear:'远程贯穿，最多命中 3 名敌人。',fan:'扇形冰羽，命中减速 2 秒。',ring:'周身范围火环，命中所有附近敌人。'})[g.weapon]}</p></div><div class="equipped-relics">${Object.entries(g.relics).length?Object.entries(g.relics).map(([key,level])=>`<div><strong>${RELICS[key].icon} ${RELICS[key].name} · ${level} 级</strong><p>${RELICS[key].desc}</p></div>`).join(''):'<p>尚无法宝 · 在宝箱中寻找</p>'}</div><p class="equipment-stats">攻击 ${Math.round(g.player.attack)} · 生命 ${Math.round(g.player.maxHp)} · 已开宝箱 ${g.totalChests}</p>`;}
